window.InterviewContent.materials.push(
{"id":"html:document-structure","topic":"html","tab":"junior","ordinal":1,"targetLevel":"junior","angles":[],"kind":"question","title":"Зачем документу doctype, head и body?","shortAnswer":"Doctype включает стандартный режим; head содержит метаданные, body — содержимое.","explanation":"Без корректного doctype возможен quirks mode. Заголовок страницы задаётся title, а не видимым h1.","assessment":{"basic":"Различает head и body.","confident":"Объясняет standards mode. Doctype включает стандартный режим; head содержит метаданные, body — содержимое.","deep":"Сравнить document.compatMode и вычисленные стили; связать различие с режимом разбора, а не с текстом статьи."},"followUps":[{"kind":"support","question":"Где браузер покажет содержимое title?","expected":"На вкладке или в заголовке окна, а не вместо заголовка статьи."},{"kind":"transfer","question":"Как исследовать старую страницу, которая без doctype выглядит иначе?","expected":"Сравнить document.compatMode и вычисленные стили; связать различие с режимом разбора, а не с текстом статьи."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Составьте HTML страницы новости: у неё есть заголовок вкладки и заголовок над статьёй. Объясните структуру и предскажите последствия удаления doctype."},
{"id":"html:semantic-elements","topic":"html","tab":"junior","ordinal":2,"targetLevel":"junior","angles":[],"kind":"question","title":"Как выбрать между div, article и section?","shortAnswer":"Article самостоятелен; section группирует тематический раздел; div не несёт семантики.","explanation":"Семантический элемент выбирают по смыслу, не внешнему виду. Разделу обычно нужен заголовок.","assessment":{"basic":"Называет назначение div.","confident":"Различает article и section. Article самостоятелен; section группирует тематический раздел; div не несёт семантики.","deep":"Самостоятельные комментарии могут быть вложенными article; оформление само по себе не определяет элемент."},"followUps":[{"kind":"support","question":"Можно ли прочитать новость отдельно от подборки?","expected":"Да; самостоятельность содержимого обосновывает article."},{"kind":"transfer","question":"Внутри новости появились комментарии с авторами. Как изменится структура?","expected":"Самостоятельные комментарии могут быть вложенными article; оформление само по себе не определяет элемент."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Разметьте страницу журнала с новостью, подборкой по теме и обёрткой двух колонок. Обоснуйте выбор элементов."},
{"id":"html:headings","topic":"html","tab":"junior","ordinal":3,"targetLevel":"junior","angles":[],"kind":"question","title":"Как построить иерархию заголовков?","shortAnswer":"h1–h6 отражают вложенность разделов.","explanation":"Размер текста регулирует CSS. Логическая иерархия помогает навигации по заголовкам; section сам не перенумеровывает h1.","assessment":{"basic":"Знает уровни h1–h6.","confident":"Разделяет размер и смысл. h1–h6 отражают вложенность разделов.","deep":"Согласовать уровни с окружающим документом и проверить навигацию по заголовкам, не рассчитывая на автоматическое перенумерование section."},"followUps":[{"kind":"support","question":"Какой раздел содержит урок?","expected":"Модуль; уровень урока отражает эту вложенность."},{"kind":"transfer","question":"Курс вставили в раздел большого портала. Что проверите у заголовков?","expected":"Согласовать уровни с окружающим документом и проверить навигацию по заголовкам, не рассчитывая на автоматическое перенумерование section."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Предложите заголовки для курса, его модулей и уроков. Название одного урока должно выглядеть крупнее названия модуля. Покажите разметку и оформление."},
{"id":"html:links-buttons","topic":"html","tab":"junior","ordinal":4,"targetLevel":"junior","angles":[],"kind":"question","title":"Когда нужен a, а когда button?","shortAnswer":"Ссылка переходит к ресурсу, кнопка выполняет действие.","explanation":"У a нужен реальный href. Нативная кнопка уже поддерживает клавиатуру, disabled и фокус.","assessment":{"basic":"Различает переход и действие.","confident":"Использует нативные элементы. Ссылка переходит к ресурсу, кнопка выполняет действие.","deep":"Оставить настоящую ссылку с адресом и сохранить открытие в новой вкладке и работу без перехвата."},"followUps":[{"kind":"support","question":"Какой из элементов должен иметь адрес назначения?","expected":"Переход к профилю; ссылка с href сохраняет браузерную навигацию."},{"kind":"transfer","question":"Профиль теперь открывает клиентский роутер. Нужно ли менять элемент?","expected":"Оставить настоящую ссылку с адресом и сохранить открытие в новой вкладке и работу без перехвата."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Разметьте «Открыть профиль» и «Удалить черновик», одинаковые по дизайну. Объясните поведение обоих элементов с клавиатуры."},
{"id":"html:image-alt","topic":"html","tab":"junior","ordinal":5,"targetLevel":"junior","angles":[],"kind":"question","title":"Как написать alt для изображения?","shortAnswer":"Alt передаёт функцию или смысл изображения; декоративному нужен пустой alt.","explanation":"Отсутствующий alt не равен пустому: скринридер может прочитать имя файла. У ссылки-картинки важна цель перехода.","assessment":{"basic":"Отличает декор от содержания.","confident":"Пишет функциональный alt. Alt передаёт функцию или смысл изображения; декоративному нужен пустой alt.","deep":"Избежать дублирования доступного имени; у изображения может быть пустой alt при достаточном тексте ссылки."},"followUps":[{"kind":"support","question":"Какой смысл потеряется при удалении декоративной полоски?","expected":"Никакой содержательный смысл; подходит пустой alt."},{"kind":"transfer","question":"Рядом с логотипом внутри той же ссылки уже написано «На главную». Как изменится alt?","expected":"Избежать дублирования доступного имени; у изображения может быть пустой alt при достаточном тексте ссылки."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Назначьте текстовые альтернативы фотографии товара, декоративной полоске и логотипу-ссылке на главную. Объясните каждое решение."},
{"id":"html:lists","topic":"html","tab":"junior","ordinal":6,"targetLevel":"junior","angles":[],"kind":"question","title":"Чем отличаются ul, ol и dl?","shortAnswer":"ul — набор, ol — значимый порядок, dl — группы терминов и описаний.","explanation":"Порядок рецепта важен, порядок тегов обычно нет. Семантика списка доступна вспомогательным технологиям.","assessment":{"basic":"Выбирает ul или ol.","confident":"Использует dt и dd. ul — набор, ol — значимый порядок, dl — группы терминов и описаний.","deep":"Сохранить один список либо обоснованно продолжить нумерацию через start; визуальная вставка не должна менять смысл порядка."},"followUps":[{"kind":"support","question":"Изменится ли рецепт при перестановке шагов?","expected":"Да, порядок значим; уместен ol."},{"kind":"transfer","question":"Нумерация рецепта продолжается после вставки фотографии. Как сохранить последовательность?","expected":"Сохранить один список либо обоснованно продолжить нумерацию через start; визуальная вставка не должна менять смысл порядка."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Разметьте рецепт, метки статьи и словарь терминов. У второго шага рецепта есть подпункты; покажите их вложенность."},
{"id":"html:labels","topic":"html","tab":"junior","ordinal":7,"targetLevel":"junior","angles":[],"kind":"question","title":"Как связать подпись с полем?","shortAnswer":"Использовать label с for, совпадающим с id поля, либо вложить поле в label.","explanation":"Placeholder исчезает при вводе и не заменяет подпись. Связанный label увеличивает область активации.","assessment":{"basic":"Связывает for и id.","confident":"Отличает label от placeholder. Использовать label с for, совпадающим с id поля, либо вложить поле в label.","deep":"Назначить уникальные id каждому экземпляру и согласованно обновить for, проверив обе подписи."},"followUps":[{"kind":"support","question":"Какие значения нужно сопоставить у label и input?","expected":"for подписи и уникальный id поля, либо использовать допустимое вложение в label."},{"kind":"transfer","question":"На странице появились два экземпляра формы. Как избежать перекрёстного фокуса?","expected":"Назначить уникальные id каждому экземпляру и согласованно обновить for, проверив обе подписи."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Нажатие подписи «Почта» не переводит фокус в поле. Покажите исправление разметки и способ проверить его."},
{"id":"html:input-types","topic":"html","tab":"junior","ordinal":8,"targetLevel":"junior","angles":[],"kind":"question","title":"Зачем выбирать type у input?","shortAnswer":"Тип задаёт семантику, клавиатуру и встроенные ограничения.","explanation":"email проверяет базовый формат, но не существование адреса. Сервер всё равно валидирует полученные данные.","assessment":{"basic":"Выбирает email и number.","confident":"Объясняет встроенную проверку. Тип задаёт семантику, клавиатуру и встроенные ограничения.","deep":"Не терять ноль; текстовый контракт, подходящая клавиатура и проверки формата конкретной страны."},"followUps":[{"kind":"support","question":"Нужно ли складывать или сравнивать номер телефона как число?","expected":"Нет; телефон является строковым идентификатором, а не количеством."},{"kind":"transfer","question":"Добавили почтовый индекс с ведущим нулём. Какое поле и хранение предложите?","expected":"Не терять ноль; текстовый контракт, подходящая клавиатура и проверки формата конкретной страны."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Выберите поля для почты, количества товара и телефона в форме заказа. Объясните ввод на мобильном устройстве и границы браузерной проверки."},
{"id":"html:form-submit","topic":"html","tab":"junior","ordinal":9,"targetLevel":"junior","angles":[],"kind":"question","title":"Что происходит при отправке формы?","shortAnswer":"Браузер собирает успешные элементы с name и отправляет по action и method.","explanation":"Поле без name не входит в данные. Кнопка внутри формы без type обычно становится submit.","assessment":{"basic":"Знает action и method.","confident":"Понимает роль name. Браузер собирает успешные элементы с name и отправляет по action и method.","deep":"Принять несколько значений одного имени, не сводя запрос к объекту с единственным значением."},"followUps":[{"kind":"support","question":"Как браузер узнаёт имя параметра поля?","expected":"Из name; одного id недостаточно."},{"kind":"transfer","question":"У двух отмеченных флажков одинаковый name. Как серверу получить оба выбора?","expected":"Принять несколько значений одного имени, не сводя запрос к объекту с единственным значением."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Форма отправляется, но одно заполненное поле отсутствует в запросе. Объясните путь отправки и покажите порядок диагностики."},
{"id":"html:boolean-attributes","topic":"html","tab":"junior","ordinal":10,"targetLevel":"junior","angles":[],"kind":"question","title":"Почему disabled=\"false\" отключает поле?","shortAnswer":"Для булевого атрибута важен факт присутствия, а не текст значения.","explanation":"Чтобы включить поле, атрибут удаляют. Это отличается от перечислимых атрибутов вроде contenteditable.","assessment":{"basic":"Узнаёт булев атрибут.","confident":"Удаляет disabled для включения. Для булевого атрибута важен факт присутствия, а не текст значения.","deep":"Нет; ARIA использует строковые значения, false не равен true."},"followUps":[{"kind":"support","question":"Присутствует ли disabled в исходной разметке?","expected":"Да; для булевого атрибута присутствие включает состояние."},{"kind":"transfer","question":"Можно ли так же трактовать aria-hidden=\"false\"?","expected":"Нет; ARIA использует строковые значения, false не равен true."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Поле с disabled=\"false\" недоступно. Предскажите результат удаления атрибута и объясните оба состояния.","questionCode":"<input type=\"text\" disabled=\"false\">\n<input type=\"checkbox\" checked=\"false\">","questionCodeLanguage":"html"},
{"id":"html:tables","topic":"html","tab":"junior","ordinal":11,"targetLevel":"junior","angles":[],"kind":"question","title":"Как разметить таблицу данных?","shortAnswer":"Использовать table, строки tr, заголовки th и ячейки td; дать caption.","explanation":"Таблица выражает отношения данных. scope у простых заголовков помогает связать строку или столбец с ячейками.","assessment":{"basic":"Строит строки и ячейки.","confident":"Добавляет caption и scope. Использовать table, строки tr, заголовки th и ячейки td; дать caption.","deep":"Связи многоуровневых заголовков с данными; при необходимости явные headers/id либо упрощение таблицы."},"followUps":[{"kind":"support","question":"Какие два заголовка относятся к одной продаже?","expected":"Сотрудник и месяц; нужны заголовки строки и столбца."},{"kind":"transfer","question":"В отчёте появились группы месяцев по кварталам. Что проверите?","expected":"Связи многоуровневых заголовков с данными; при необходимости явные headers/id либо упрощение таблицы."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Разметьте отчёт о продажах по сотрудникам и месяцам так, чтобы смысл числа был понятен при навигации по ячейкам."},
{"id":"html:language","topic":"html","tab":"junior","ordinal":12,"targetLevel":"junior","angles":[],"kind":"question","title":"Для чего lang у html?","shortAnswer":"Он сообщает язык содержимого браузеру и вспомогательным технологиям.","explanation":"Правильный язык влияет на произношение. Иноязычный фрагмент может иметь собственный lang.","assessment":{"basic":"Устанавливает lang=\"ru\".","confident":"Меняет язык фрагмента. Он сообщает язык содержимого браузеру и вспомогательным технологиям.","deep":"При необходимости отметить язык вложенного фрагмента и проверить произношение в целевой вспомогательной технологии."},"followUps":[{"kind":"support","question":"Какой атрибут сообщает язык всего документа?","expected":"lang на html; он задаёт язык, а не кодировку."},{"kind":"transfer","question":"Цитата содержит русское имя внутри английского предложения. Как уточните разметку?","expected":"При необходимости отметить язык вложенного фрагмента и проверить произношение в целевой вспомогательной технологии."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"В русской статье английская цитата звучит неверно при чтении экранной программой. Предложите исправление и проверку."},
{"id":"html:script-basics","topic":"html","tab":"junior","ordinal":13,"targetLevel":"junior","angles":[],"kind":"question","title":"Где подключить скрипт, использующий DOM?","shortAnswer":"Использовать defer либо модуль; они выполняются после разбора документа.","explanation":"Обычный блокирующий script в head может обратиться к ещё не созданному элементу. Defer сохраняет порядок классических скриптов.","assessment":{"basic":"Видит проблему раннего доступа.","confident":"Использует defer. Использовать defer либо модуль; они выполняются после разбора документа.","deep":"Для классических defer учитывать порядок тегов; для модулей выразить зависимость импортом, а не надеяться на скорость сети."},"followUps":[{"kind":"support","question":"Существует ли кнопка в момент выполнения обычного скрипта в head?","expected":"Парсер мог ещё не дойти до кнопки."},{"kind":"transfer","question":"После исправления подключили вторую зависимую библиотеку. Как сохранить порядок?","expected":"Для классических defer учитывать порядок тегов; для модулей выразить зависимость импортом, а не надеяться на скорость сети."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Скрипт в head ищет кнопку в конце body и получает null. Предложите исправление подключения и объясните порядок событий."},
{"id":"html:validation-message","topic":"html","tab":"junior","ordinal":14,"targetLevel":"junior","angles":[],"kind":"question","title":"Как показать понятную ошибку поля?","shortAnswer":"Связать текст ошибки с полем через aria-describedby и отметить aria-invalid после проверки.","explanation":"Сообщение объясняет исправление. Цвет рамки без текста не помогает понять причину и недоступен части пользователей.","assessment":{"basic":"Пишет текст ошибки.","confident":"Связывает ошибку с полем. Связать текст ошибки с полем через aria-describedby и отметить aria-invalid после проверки.","deep":"Показать общий доступный статус формы, сохранить введённые данные и дать понятный путь повторной попытки."},"followUps":[{"kind":"support","question":"Что должен сообщить текст ошибки кроме факта неудачи?","expected":"Причину и способ исправления, например ожидаемый формат адреса."},{"kind":"transfer","question":"Сервер отклонил всю заявку, не выделив поле. Куда поместите сообщение?","expected":"Показать общий доступный статус формы, сохранить введённые данные и дать понятный путь повторной попытки."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Ошибка почты обозначена только красной рамкой. Покажите доступное сообщение, его связь с полем и момент появления."},
{"id":"html:accessible-dialog","topic":"html","tab":"junior","ordinal":15,"targetLevel":"junior","angles":[],"kind":"question","title":"Что нужно модальному окну кроме затемнения?","shortAnswer":"Доступное имя, управление фокусом, закрытие и возврат фокуса.","explanation":"Нативный dialog с showModal делает фон инертным. После закрытия пользователь должен продолжить работу с вызывающей кнопки.","assessment":{"basic":"Называет фокус и закрытие.","confident":"Использует dialog и имя. Доступное имя, управление фокусом, закрытие и возврат фокуса.","deep":"Выбрать существующий логический следующий элемент, а не пытаться сфокусировать удалённый узел."},"followUps":[{"kind":"support","question":"Где находится фокус сразу после открытия?","expected":"В подходящем элементе диалога; пользователь должен понимать контекст."},{"kind":"transfer","question":"Кнопка открытия исчезла во время работы окна. Куда вернуть фокус?","expected":"Выбрать существующий логический следующий элемент, а не пытаться сфокусировать удалённый узел."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Спроектируйте поведение окна подтверждения удаления от открытия до отмены для пользователя клавиатуры."},
{"id":"html:content-model","topic":"html","tab":"middle","ordinal":1,"targetLevel":"middle","angles":[],"kind":"question","title":"Почему нельзя вложить button в ссылку?","shortAnswer":"Интерактивные потомки нарушают модель содержимого ссылки.","explanation":"Два действия получают неоднозначную активацию. Нужно разделить самостоятельные элементы, сохранив понятные зоны клика.","assessment":{"basic":"Обнаруживает вложенную интерактивность.","confident":"Предлагает отдельные элементы. Интерактивные потомки нарушают модель содержимого ссылки.","deep":"Предложить отдельную основную ссылку с осторожным расширением зоны клика; проверить наложения, фокус и вложенные действия."},"followUps":[{"kind":"support","question":"Сколько независимых действий должно быть доступно?","expected":"Два: переход и изменение избранного; нужны отдельные интерактивные элементы."},{"kind":"transfer","question":"Заказчик требует кликабельную всю площадь карточки. Как сохраните выделение текста и действия?","expected":"Предложить отдельную основную ссылку с осторожным расширением зоны клика; проверить наложения, фокус и вложенные действия."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Ссылка оборачивает карточку товара вместе с кнопкой «В избранное». Исправьте структуру и проверьте оба действия."},
{"id":"html:responsive-images","topic":"html","tab":"middle","ordinal":2,"targetLevel":"middle","angles":[],"kind":"question","title":"Как браузер выбирает ресурс из srcset и sizes?","shortAnswer":"sizes сообщает предполагаемую ширину слота; srcset предлагает кандидаты.","explanation":"При дескрипторах w браузер учитывает слот и плотность экрана. CSS-размер изображения отдельно определяет раскладку.","assessment":{"basic":"Различает w и x.","confident":"Правильно задаёт sizes. sizes сообщает предполагаемую ширину слота; srcset предлагает кандидаты.","deep":"Соответствие sizes реальной раскладке и выбранный currentSrc; неверное описание может вести к лишней загрузке."},"followUps":[{"kind":"support","question":"Какую ширину описывает sizes?","expected":"Предполагаемую ширину слота в раскладке, не физическую ширину файла."},{"kind":"transfer","question":"Боковая панель сузила слот без изменения viewport. Что проверите?","expected":"Соответствие sizes реальной раскладке и выбранный currentSrc; неверное описание может вести к лишней загрузке."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Фотография занимает экран телефона и треть широкого экрана. Есть файлы 400, 800 и 1600 px. Составьте разметку выбора ресурса и объясните проверку на разных экранах."},
{"id":"html:picture-art","topic":"html","tab":"middle","ordinal":3,"targetLevel":"middle","angles":[],"kind":"question","title":"Как менять кадрирование для мобильного экрана?","shortAnswer":"Использовать picture с media у source и резервным img.","explanation":"Picture позволяет art direction, а не только выбор разрешения. Alt остаётся у img, поскольку смысл изображения общий.","assessment":{"basic":"Выбирает picture.","confident":"Указывает media и fallback. Использовать picture с media у source и резервным img.","deep":"Совместить условия media и type в source, сохранить резервный img и единую осмысленную альтернативу."},"followUps":[{"kind":"support","question":"Достаточно ли увеличить разрешение общего плана для нужного портрета?","expected":"Нет; требуется другой кадр, а не только плотность пикселей."},{"kind":"transfer","question":"К каждому кадру добавили AVIF и резервный формат. Как организуете варианты?","expected":"Совместить условия media и type в source, сохранить резервный img и единую осмысленную альтернативу."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"На телефоне нужен крупный портрет, на широком экране — общий план той же сцены. Предложите разметку и объясните выбор файла."},
{"id":"html:resource-order","topic":"html","tab":"middle","ordinal":4,"targetLevel":"middle","angles":[],"kind":"question","title":"Чем отличаются async, defer и module?","shortAnswer":"Async исполняется по готовности; defer — после разбора в порядке; модуль по умолчанию отложен.","explanation":"Async не гарантирует порядок зависимых классических скриптов. Модули используют собственный граф зависимостей.","assessment":{"basic":"Различает порядок выполнения.","confident":"Учитывает DOMContentLoaded. Async исполняется по готовности; defer — после разбора в порядке; модуль по умолчанию отложен.","deep":"Выразить её импортом; обычный модуль отложен относительно разбора, а async изменяет этот режим."},"followUps":[{"kind":"support","question":"Может ли зависимый скрипт исполниться раньше библиотеки при async?","expected":"Да; async не обеспечивает порядок этих файлов."},{"kind":"transfer","question":"Интерфейс перевели на модули. Как выразить зависимость и когда ждать DOM?","expected":"Выразить её импортом; обычный модуль отложен относительно разбора, а async изменяет этот режим."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Подключите библиотеку, зависимый интерфейс и независимую аналитику. Обоснуйте порядок исполнения при произвольной скорости загрузки."},
{"id":"html:formdata","topic":"html","tab":"middle","ordinal":5,"targetLevel":"middle","angles":[],"kind":"question","title":"Какие значения попадут в FormData(form)?","shortAnswer":"Успешные элементы с name; disabled и неотмеченные checkbox исключаются.","explanation":"Readonly обычно отправляется. Для нескольких значений одного имени используют getAll, иначе часть данных теряется.","assessment":{"basic":"Перечисляет исключения.","confident":"Различает readonly и disabled. Успешные элементы с name; disabled и неотмеченные checkbox исключаются.","deep":"Передать подходящий submitter при построении FormData либо явно добавить действие, согласовав контракт."},"followUps":[{"kind":"support","question":"Будет ли неотмеченный checkbox представлен записью false?","expected":"Нет; неотмеченный флажок исключается."},{"kind":"transfer","question":"Сохранение и публикация имеют разные name/value кнопок. Как включить выбранное действие?","expected":"Передать подходящий submitter при построении FormData либо явно добавить действие, согласовав контракт."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Предскажите FormData формы с readonly, disabled, полем без name и двумя checkbox одного имени. Покажите чтение всех выбранных значений.","questionCode":"<form id=\"order\">\n  <input name=\"code\" value=\"A1\" readonly>\n  <input name=\"discount\" value=\"10\" disabled>\n  <input type=\"checkbox\" name=\"option\" value=\"gift\" checked>\n  <input type=\"checkbox\" name=\"option\" value=\"call\">\n  <input value=\"note\">\n</form>","questionCodeLanguage":"html"},
{"id":"html:constraint-validation","topic":"html","tab":"middle","ordinal":6,"targetLevel":"middle","angles":[],"kind":"question","title":"Как совместить встроенную и серверную валидацию?","shortAnswer":"Проверять ограничения на клиенте для удобства и повторять доверенные проверки на сервере.","explanation":"checkValidity возвращает результат, reportValidity ещё показывает сообщение. setCustomValidity нужно очищать после исправления.","assessment":{"basic":"Не доверяет только клиенту.","confident":"Использует validation API. Проверять ограничения на клиенте для удобства и повторять доверенные проверки на сервере.","deep":"Связать результат с проверяемым значением или запросом; устаревшая ошибка не должна применяться к новому адресу."},"followUps":[{"kind":"support","question":"Что означает непустая строка setCustomValidity?","expected":"Поле остаётся недействительным, пока пользовательская ошибка не очищена."},{"kind":"transfer","question":"Ответ проверки старого адреса пришёл после нового. Как защитить форму?","expected":"Связать результат с проверяемым значением или запросом; устаревшая ошибка не должна применяться к новому адресу."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"После серверной ошибки «Адрес занят» пользователь меняет почту, но отправка остаётся заблокирована. Найдите причину и предложите жизненный цикл проверки."},
{"id":"html:autofill","topic":"html","tab":"middle","ordinal":7,"targetLevel":"middle","angles":[],"kind":"question","title":"Как помочь менеджеру паролей и автозаполнению?","shortAnswer":"Использовать стандартные autocomplete-токены и стабильные подписи полей.","explanation":"current-password и new-password имеют разный смысл. Запрет вставки мешает менеджерам паролей и не повышает надёжность проверки.","assessment":{"basic":"Знает autocomplete.","confident":"Различает типы пароля. Использовать стандартные autocomplete-токены и стабильные подписи полей.","deep":"Разделить группы стандартными autocomplete-токенами и ясными подписями; проверить реальный браузер."},"followUps":[{"kind":"support","question":"Чем текущий пароль отличается от создаваемого для менеджера паролей?","expected":"Это разные назначения; подходят current-password и new-password."},{"kind":"transfer","question":"На странице одновременно доставка и платёжный адрес. Как уменьшить путаницу автозаполнения?","expected":"Разделить группы стандартными autocomplete-токенами и ясными подписями; проверить реальный браузер."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Спроектируйте вход, смену пароля и подтверждение кодом с удобным автозаполнением. Оцените предложение запретить вставку пароля."},
{"id":"html:details","topic":"html","tab":"middle","ordinal":8,"targetLevel":"middle","angles":[],"kind":"question","title":"Когда подходит details/summary?","shortAnswer":"Для необязательного раскрываемого содержимого с нативной клавиатурной активацией.","explanation":"Summary даёт имя раскрытию. Контент, необходимый для основного действия, не стоит прятать без причины.","assessment":{"basic":"Строит details и summary.","confident":"Понимает состояние open. Для необязательного раскрываемого содержимого с нативной клавиатурной активацией.","deep":"Обязательное сообщение должно быть обнаружимо без необязательного раскрытия; пересмотреть размещение и подтверждение."},"followUps":[{"kind":"support","question":"Какой элемент даёт видимую подпись details?","expected":"summary служит управляющей подписью раскрытия."},{"kind":"transfer","question":"Справка стала обязательным предупреждением перед отправкой. Оставите её закрытой?","expected":"Обязательное сообщение должно быть обнаружимо без необязательного раскрытия; пересмотреть размещение и подтверждение."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Справку к полю нужно раскрывать по запросу. Выберите HTML-структуру и объясните клавиатурное поведение."},
{"id":"html:inert-hidden","topic":"html","tab":"middle","ordinal":9,"targetLevel":"middle","angles":[],"kind":"question","title":"Чем отличаются hidden и inert?","shortAnswer":"Hidden скрывает содержимое; inert исключает взаимодействие и фокус в поддереве.","explanation":"Инертная область может оставаться видимой. Одного aria-hidden недостаточно, чтобы убрать кнопку из клавиатурного порядка.","assessment":{"basic":"Различает видимость и интерактивность.","confident":"Убирает фокус из скрытого. Hidden скрывает содержимое; inert исключает взаимодействие и фокус в поддереве.","deep":"Она тоже станет недоступна для взаимодействия; изменить границу контейнера и проверить доступность панели."},"followUps":[{"kind":"support","question":"Нужно ли скрыть фон визуально по условию?","expected":"Нет; inert подходит для исключения взаимодействия с видимым поддеревом."},{"kind":"transfer","question":"Панель случайно находится внутри отключённого контейнера. Что произойдёт?","expected":"Она тоже станет недоступна для взаимодействия; изменить границу контейнера и проверить доступность панели."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"При открытии панели фон остаётся видимым, но не должен принимать действия. Сравните подходящие способы разметки и проверьте фокус."},
{"id":"html:focus-order","topic":"html","tab":"middle","ordinal":10,"targetLevel":"middle","angles":[],"kind":"question","title":"Как построить порядок фокуса в сложной форме?","shortAnswer":"Согласовать DOM с визуальным порядком, использовать нативные элементы и избегать положительного tabindex.","explanation":"Tabindex=0 включает элемент в естественный порядок, -1 оставляет программный фокус. CSS order не меняет DOM-порядок чтения.","assessment":{"basic":"Знает 0 и -1.","confident":"Избегает положительного tabindex. Согласовать DOM с визуальным порядком, использовать нативные элементы и избегать положительного tabindex.","deep":"Выбрать логический DOM-порядок для обоих представлений и проверить чтение и Tab, избегая положительных tabindex."},"followUps":[{"kind":"support","question":"Каков обычный источник последовательности фокуса?","expected":"Порядок доступных элементов в DOM, если его не переопределяют."},{"kind":"transfer","question":"На мобильном колонки меняются местами. Как сохранить понятное чтение?","expected":"Выбрать логический DOM-порядок для обоих представлений и проверить чтение и Tab, избегая положительных tabindex."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Визуальный порядок полей формы не совпадает с Tab-порядком. Предложите исправление, устойчивое к адаптивной раскладке."},
{"id":"html:fieldset","topic":"html","tab":"middle","ordinal":11,"targetLevel":"middle","angles":[],"kind":"question","title":"Как сгруппировать связанные radio-поля?","shortAnswer":"Общий name задаёт группу, fieldset и legend дают её подпись.","explanation":"Подпись отдельной опции не объясняет вопрос группы. Нативные radio поддерживают ожидаемую стрелочную навигацию.","assessment":{"basic":"Создаёт группу name.","confident":"Добавляет legend. Общий name задаёт группу, fieldset и legend дают её подпись.","deep":"Дать разные имена независимым группам и отдельные понятные legend, чтобы выбор одной не сбрасывал другую."},"followUps":[{"kind":"support","question":"Что объединяет radio в одну группу выбора?","expected":"Общий name в соответствующей группе формы."},{"kind":"transfer","question":"Появились две независимые посылки. Как изменить группы?","expected":"Дать разные имена независимым группам и отдельные понятные legend, чтобы выбор одной не сбрасывал другую."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Разметьте выбор одного способа доставки из трёх с общей подписью. Покажите поведение при выборе и отправке."},
{"id":"html:iframe-boundary","topic":"html","tab":"middle","ordinal":12,"targetLevel":"middle","angles":[],"kind":"question","title":"Что учитывать при встраивании iframe?","shortAnswer":"Доступное title, границу origin, ограничения sandbox и разрешения permissions policy.","explanation":"Same-origin policy ограничивает доступ к чужому документу. Sandbox нужно выдавать минимально; комбинации разрешений могут ослаблять изоляцию.","assessment":{"basic":"Знает title и origin.","confident":"Выбирает sandbox-разрешения. Доступное title, границу origin, ограничения sandbox и разрешения permissions policy.","deep":"Минимально необходимые разрешения, доверенные origin и проверяемую схему сообщений; iframe сам не делает содержимое доверенным."},"followUps":[{"kind":"support","question":"Что поможет пользователю понять назначение iframe?","expected":"Осмысленный title, описывающий встроенное содержимое."},{"kind":"transfer","question":"Виджет просит доступ к камере и присылает сообщения. Что согласуете?","expected":"Минимально необходимые разрешения, доверенные origin и проверяемую схему сообщений; iframe сам не делает содержимое доверенным."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Нужно встроить сторонний виджет. Предложите разметку iframe и проверки доступности, разрешений и обмена данными."},
{"id":"html:native-popover","topic":"html","tab":"middle","ordinal":13,"targetLevel":"middle","angles":[],"kind":"question","title":"Чем popover отличается от модального dialog?","shortAnswer":"Popover обычно немодален и не блокирует остальную страницу.","explanation":"Popover API управляет показом и light-dismiss, но семантику меню или диалога выбирает автор. Проверять поддержку в целевых браузерах.","assessment":{"basic":"Различает модальность.","confident":"Учитывает light-dismiss. Popover обычно немодален и не блокирует остальную страницу.","deep":"Потребуется модальный контракт, например dialog.showModal, с фокусом и возвратом; popover сам его не обеспечивает."},"followUps":[{"kind":"support","question":"Нужно ли блокировать всю страницу ради этой справки?","expected":"Нет; это немодальный сценарий."},{"kind":"transfer","question":"Вместо справки появилось обязательное подтверждение удаления. Как изменится выбор?","expected":"Потребуется модальный контракт, например dialog.showModal, с фокусом и возвратом; popover сам его не обеспечивает."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Выберите поведение для всплывающей справки рядом с кнопкой: остальная страница должна оставаться доступной. Обоснуйте HTML-механизм."},
{"id":"html:loading-image","topic":"html","tab":"middle","ordinal":14,"targetLevel":"middle","angles":[],"kind":"question","title":"Как снизить сдвиги при загрузке изображений?","shortAnswer":"Задать width/height либо aspect-ratio для резервирования места.","explanation":"Lazy-loading подходит изображениям ниже первого экрана. Главный LCP-ресурс не стоит бездумно откладывать.","assessment":{"basic":"Резервирует пропорции.","confident":"Выбирает loading по контексту. Задать width/height либо aspect-ratio для резервирования места.","deep":"Измерить LCP; откладывание важного изображения может ухудшить его, в отличие от изображений ниже экрана."},"followUps":[{"kind":"support","question":"Известно ли место изображения до загрузки файла?","expected":"Его можно зарезервировать размерами или соотношением сторон."},{"kind":"transfer","question":"Главная фотография стала крупнейшим видимым элементом. Как оцените lazy-loading?","expected":"Измерить LCP; откладывание важного изображения может ухудшить его, в отличие от изображений ниже экрана."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"При загрузке фотографий текст страницы прыгает. Предложите исправление и порядок загрузки изображений первого и последующих экранов."},
{"id":"html:safe-html","topic":"html","tab":"middle","ordinal":15,"targetLevel":"middle","angles":[],"kind":"question","title":"Почему вставка пользовательской строки через innerHTML опасна?","shortAnswer":"Строка разбирается как разметка и может создать опасные узлы и обработчики.","explanation":"Для текста применять textContent. Если HTML необходим, нужна проверенная санитаризация; экранирование зависит от контекста вставки.","assessment":{"basic":"Выбирает textContent.","confident":"Разделяет текст и HTML. Строка разбирается как разметка и может создать опасные узлы и обработчики.","deep":"Нужна проверенная санитаризация с ограниченным набором тегов и URL, а не простая замена пары символов."},"followUps":[{"kind":"support","question":"Нужна ли разметка для обычного текстового комментария?","expected":"Нет; текстовый вывод не должен интерпретировать теги."},{"kind":"transfer","question":"Разрешили ссылки и выделение текста. Как изменится обработка?","expected":"Нужна проверенная санитаризация с ограниченным набором тегов и URL, а не простая замена пары символов."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Комментарий пользователя вставляется через innerHTML. Опишите риск и безопасный путь отображения с учётом требования к форматированию."},
{"id":"html:ssr-parser","topic":"html","tab":"senior","ordinal":1,"targetLevel":"senior","angles":[],"kind":"case","title":"SSR-страница визуально верна, но гидратация ломается: с чего начать?","shortAnswer":"Сравнить серверную строку с DOM после работы HTML-парсера и клиентским деревом.","explanation":"Неверные вложения могут автоматически закрыть p или добавить tbody. Гидратируется исправленный DOM, а не исходная строка.","assessment":{"basic":"Проверяет фактический DOM.","confident":"Находит исправление парсером. Сравнить серверную строку с DOM после работы HTML-парсера и клиентским деревом.","deep":"Серверную строку, DOM с возможным tbody и клиентское ожидаемое дерево; согласовать явную структуру."},"followUps":[{"kind":"support","question":"Одинаковы ли строка HTML и дерево, построенное парсером?","expected":"Не обязательно; парсер исправляет недопустимые вложения."},{"kind":"transfer","question":"Ошибка появляется только в таблице. Какие три представления сравните?","expected":"Серверную строку, DOM с возможным tbody и клиентское ожидаемое дерево; согласовать явную структуру."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"После серверного рендера гидратация жалуется на дерево, хотя HTML выглядит правдоподобно. Предложите воспроизведение и поиск причины."},
{"id":"html:form-resilience","topic":"html","tab":"senior","ordinal":2,"targetLevel":"senior","angles":[],"kind":"case","title":"Как спроектировать форму, работающую до загрузки JavaScript?","shortAnswer":"Сохранить action, method и нативную отправку; JS улучшает обратную связь.","explanation":"Progressive enhancement оставляет путь отправки при сбое скрипта. Ошибки сервера возвращают значения и привязанные сообщения.","assessment":{"basic":"Сохраняет нативный submit.","confident":"Обрабатывает серверные ошибки. Сохранить action, method и нативную отправку; JS улучшает обратную связь.","deep":"Подключить улучшение к существующей форме, сохранить значения и обеспечить единственный путь отправки каждого действия."},"followUps":[{"kind":"support","question":"Какие атрибуты позволят отправить форму без обработчика JS?","expected":"Корректные action, method и name у полей."},{"kind":"transfer","question":"JS загрузился после начала заполнения. Как избежать потери ввода и двойной отправки?","expected":"Подключить улучшение к существующей форме, сохранить значения и обеспечить единственный путь отправки каждого действия."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Регистрация должна работать при отказе JavaScript, а при его наличии — давать быстрый отклик. Спроектируйте отправку и восстановление после ошибки."},
{"id":"html:dialog-system","topic":"html","tab":"senior","ordinal":3,"targetLevel":"senior","angles":[],"kind":"case","title":"Как проверить общую библиотеку модальных окон?","shortAnswer":"Проверить имя, модальность, начальный фокус, Escape, вложенные сценарии и возврат фокуса.","explanation":"Перенос в top layer решает перекрытие, но не все продуктовые вопросы. При исчезновении триггера нужен осмысленный резервный фокус.","assessment":{"basic":"Составляет клавиатурный сценарий.","confident":"Учитывает удалённый триггер. Проверить имя, модальность, начальный фокус, Escape, вложенные сценарии и возврат фокуса.","deep":"Фокус возвращается в действующий первый диалог; фон остаётся недоступным, Escape закрывает ожидаемый слой."},"followUps":[{"kind":"support","question":"Что нужно запомнить перед открытием окна?","expected":"Контекст и элемент возврата фокуса, если он останется доступен."},{"kind":"transfer","question":"Второй диалог закрывается, а первый остаётся. Как проверить поведение?","expected":"Фокус возвращается в действующий первый диалог; фон остаётся недоступным, Escape закрывает ожидаемый слой."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Команда внедряет общую систему диалогов. Определите контракт и проверки для вложенных сценариев и клавиатурной работы."},
{"id":"html:accessible-table","topic":"html","tab":"senior","ordinal":4,"targetLevel":"senior","angles":[],"kind":"case","title":"Как сделать доступной таблицу со сложными заголовками?","shortAnswer":"Для сложных связей задавать id заголовков и headers ячеек; упростить структуру, если возможно.","explanation":"Слияния ячеек затрудняют понимание. Виртуализация требует отдельно сохранять доступные отношения строк и столбцов.","assessment":{"basic":"Понимает scope.","confident":"Использует явные headers. Для сложных связей задавать id заголовков и headers ячеек; упростить структуру, если возможно.","deep":"Повторить связи значения с подписями в новой структуре и проверить порядок чтения; внешний вид таблицы не единственный допустимый вариант."},"followUps":[{"kind":"support","question":"Какие заголовки описывают выбранную ячейку?","expected":"Все соответствующие уровни строки и столбца, а не только ближайшая подпись."},{"kind":"transfer","question":"На телефоне отчёт превращается в карточки. Как сохранить смысл?","expected":"Повторить связи значения с подписями в новой структуре и проверить порядок чтения; внешний вид таблицы не единственный допустимый вариант."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Отчёт содержит многоуровневые заголовки строк и столбцов. Предложите доступную структуру и стратегию проверки при ограниченном сроке."},
{"id":"html:web-component","topic":"html","tab":"senior","ordinal":5,"targetLevel":"senior","angles":[],"kind":"case","title":"Какой контракт нужен публичному custom element?","shortAnswer":"Определить атрибуты, свойства, события, доступность и поведение до upgrade.","explanation":"Атрибуты строковые, свойства могут хранить объекты. Потребитель не должен знать внутреннюю структуру shadow DOM.","assessment":{"basic":"Разделяет свойства и атрибуты.","confident":"Проектирует события. Определить атрибуты, свойства, события, доступность и поведение до upgrade.","deep":"Согласованность раннего свойства с последующей реализацией и отсутствие затенения сеттера; контракт должен покрывать этот порядок."},"followUps":[{"kind":"support","question":"Что увидит страница до регистрации элемента?","expected":"Обычный ещё не обновлённый элемент; важны начальное содержимое и доступное состояние."},{"kind":"transfer","question":"Клиент назначил свойство до upgrade. Что проверите?","expected":"Согласованность раннего свойства с последующей реализацией и отсутствие затенения сеттера; контракт должен покрывать этот порядок."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Спроектируйте публичный контракт пользовательского элемента, который может появиться до загрузки его JS. Объясните интеграцию и деградацию."},
{"id":"html:shadow-forms","topic":"html","tab":"senior","ordinal":6,"targetLevel":"senior","angles":[],"kind":"case","title":"Как включить custom element в нативную форму?","shortAnswer":"Использовать form-associated custom element и ElementInternals при поддержке среды.","explanation":"setFormValue передаёт значение форме, но валидация, disabled и восстановление состояния требуют отдельной реализации.","assessment":{"basic":"Знает ElementInternals.","confident":"Учитывает validity и disabled. Использовать form-associated custom element и ElementInternals при поддержке среды.","deep":"Предусмотреть нативный резервный контрол или ограничить поддержку явно; проверить данные, сброс и ошибки в обеих ветках."},"followUps":[{"kind":"support","question":"Попадёт ли внутренний input автоматически в данные внешней формы?","expected":"Нельзя считать это автоматическим участием через границу Shadow DOM."},{"kind":"transfer","question":"Целевая среда не поддерживает выбранный механизм. Как сохранить отправку?","expected":"Предусмотреть нативный резервный контрол или ограничить поддержку явно; проверить данные, сброс и ошибки в обеих ветках."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Пользовательское поле с Shadow DOM должно участвовать в отправке, сбросе и проверке формы. Предложите реализацию и резервный путь."},
{"id":"html:security-embed","topic":"html","tab":"senior","ordinal":7,"targetLevel":"senior","angles":[],"kind":"case","title":"Сервис вставляет недоверенный виджет: как выбрать границу?","shortAnswer":"Изолировать origin, минимизировать sandbox и разрешения, задать протокол сообщений.","explanation":"Чужой код в основном документе получает его привилегии. Проверять origin, source и схему postMessage, а не только тип сообщения.","assessment":{"basic":"Выбирает iframe.","confident":"Ограничивает разрешения. Изолировать origin, минимизировать sandbox и разрешения, задать протокол сообщений.","deep":"Рассмотреть конкретную потребность, риск и более узкий протокол через родителя; не расширять sandbox без обоснования."},"followUps":[{"kind":"support","question":"Должен ли виджет читать DOM основной страницы?","expected":"Нет; такая возможность разрушает необходимую изоляцию."},{"kind":"transfer","question":"Партнёр запрашивает навигацию верхнего окна. Как оцените изменение?","expected":"Рассмотреть конкретную потребность, риск и более узкий протокол через родителя; не расширять sandbox без обоснования."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Непроверенный партнёрский код нужно встроить в приложение с личными данными. Спроектируйте границу доверия и минимальный протокол взаимодействия."},
{"id":"html:resource-strategy","topic":"html","tab":"senior","ordinal":8,"targetLevel":"senior","angles":[],"kind":"case","title":"Как выбирать preload, preconnect и lazy-loading?","shortAnswer":"Оптимизировать измеренный критический путь, не повышать приоритет всем ресурсам.","explanation":"Preload с неверным as или CORS-режимом может не переиспользоваться. Лишние соединения и загрузки конкурируют с главным ресурсом.","assessment":{"basic":"Различает подсказки.","confident":"Учитывает повторное использование. Оптимизировать измеренный критический путь, не повышать приоритет всем ресурсам.","deep":"Сопоставить выбранный ресурс, условия и waterfall в обеих конфигурациях, исключить ненужные или двойные загрузки."},"followUps":[{"kind":"support","question":"Могут ли все запросы одновременно иметь наивысший полезный приоритет?","expected":"Нет; они конкурируют за ограниченные ресурсы."},{"kind":"transfer","question":"На мобильном критическое изображение отличается от десктопного. Как проверите подсказки загрузки?","expected":"Сопоставить выбранный ресурс, условия и waterfall в обеих конфигурациях, исключить ненужные или двойные загрузки."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"После добавления preload ко всем ресурсам первая отрисовка ухудшилась. Предложите измерение и пересмотр стратегии при ограниченном сетевом канале."},
{"id":"html:html-trust","topic":"html","tab":"senior","ordinal":9,"targetLevel":"senior","angles":[],"kind":"case","title":"Как организовать безопасный rich-text pipeline?","shortAnswer":"Ограничить разрешённый HTML, санитаризировать проверенным инструментом и избегать опасных повторных преобразований.","explanation":"Санитаризация должна учитывать контекст и URL. CSP и Trusted Types дополняют границу, а не заменяют её.","assessment":{"basic":"Называет allowlist.","confident":"Учитывает URL и преобразования. Ограничить разрешённый HTML, санитаризировать проверенным инструментом и избегать опасных повторных преобразований.","deep":"Повторно оценить итоговый контекст и преобразования: безопасный промежуточный результат может стать опасным после изменения."},"followUps":[{"kind":"support","question":"Означает ли право редактировать статью право исполнять скрипты?","expected":"Нет; разрешённые возможности должны задаваться отдельно."},{"kind":"transfer","question":"После санитаризации библиотека переписывает ссылки. Как изменится проверка?","expected":"Повторно оценить итоговый контекст и преобразования: безопасный промежуточный результат может стать опасным после изменения."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Редакторы и посетители могут добавлять форматированный текст. Спроектируйте обработку HTML от ввода до отображения и границы ответственности."},
{"id":"html:document-stream","topic":"html","tab":"senior","ordinal":10,"targetLevel":"senior","angles":[],"kind":"case","title":"Что важно для корректности потокового SSR?","shortAnswer":"Корректные HTML-вложения и порядок логических вставок; транспортные чанки сами по себе дерево не меняют.","explanation":"Парсер умеет продолжать токен между сетевыми чанками. Отдельно проверяют исполняемые скрипты, поздние SSR-вставки и клиентские маркеры, меняющие DOM.","assessment":{"basic":"Различает чанк и вставку.","confident":"Проверяет контекст парсинга. Корректные HTML-вложения и порядок логических вставок; транспортные чанки сами по себе дерево не меняют.","deep":"Проверить контекст вставки, фактический DOM и порядок логических фрагментов, а не только размеры сетевых чанков."},"followUps":[{"kind":"support","question":"Сам по себе разрыв сетевого чанка посреди тега меняет HTML?","expected":"Нет; парсер продолжает поток, важны логическая разметка и вставки."},{"kind":"transfer","question":"Поздний фрагмент содержит строки таблицы. Что добавите в тест?","expected":"Проверить контекст вставки, фактический DOM и порядок логических фрагментов, а не только размеры сетевых чанков."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"SSR отдаёт страницу потоком, и редкая ошибка гидратации возникает при вставке поздних фрагментов. Предложите план диагностики."},
{"id":"html:keyboard-widget","topic":"html","tab":"senior","ordinal":11,"targetLevel":"senior","angles":[],"kind":"case","title":"Когда оправдан кастомный виджет вместо нативного select?","shortAnswer":"Когда требования нельзя выразить нативным контролом и команда готова реализовать полный доступный контракт.","explanation":"Combobox требует управления фокусом, клавишами и объявлением состояния. Внешнее сходство с select не доказывает эквивалентность.","assessment":{"basic":"Рассматривает native-first.","confident":"Перечисляет поведенческий контракт. Когда требования нельзя выразить нативным контролом и команда готова реализовать полный доступный контракт.","deep":"Активная опция и её доступное представление должны оставаться согласованными; проверить загрузку, отсутствие результатов и удаление активного узла."},"followUps":[{"kind":"support","question":"Как пользователь выбирает опцию без мыши?","expected":"Нужны согласованные клавиши навигации, активная опция и подтверждение выбора."},{"kind":"transfer","question":"Список загружается с задержкой и виртуализируется. Что станет новым риском?","expected":"Активная опция и её доступное представление должны оставаться согласованными; проверить загрузку, отсутствие результатов и удаление активного узла."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Для большого списка клиентов предлагают собственный combobox вместо select. Оцените необходимость и определите проверяемый контракт взаимодействия."},
{"id":"html:international-form","topic":"html","tab":"senior","ordinal":12,"targetLevel":"senior","angles":[],"kind":"case","title":"Как спроектировать международную форму адреса?","shortAnswer":"Не предполагать обязательный штат, числовой индекс или западный порядок имени.","explanation":"Поля и ограничения зависят от страны. Unicode и автозаполнение важнее искусственных правил на латиницу.","assessment":{"basic":"Отказывается от жёстких допущений.","confident":"Адаптирует структуру по стране. Не предполагать обязательный штат, числовой индекс или западный порядок имени.","deep":"Пересчитать применимые поля и проверки, сохранив исходный ввод там, где это возможно, без молчаливой потери данных."},"followUps":[{"kind":"support","question":"Всегда ли индекс можно хранить числом?","expected":"Нет; возможны буквы и ведущие нули."},{"kind":"transfer","question":"Страна меняется после заполнения адреса. Как поведёт себя форма?","expected":"Пересчитать применимые поля и проверки, сохранив исходный ввод там, где это возможно, без молчаливой потери данных."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Спроектируйте форму международной доставки, хранение и проверки имени, адреса и индекса. Обоснуйте обязательность каждого поля."},
{"id":"html:content-policy","topic":"html","tab":"senior","ordinal":13,"targetLevel":"senior","angles":[],"kind":"case","title":"Как согласовать семантику контента из CMS?","shortAnswer":"Зафиксировать разрешённые блоки, уровни заголовков, подписи медиа и правила ссылок.","explanation":"Шаблон страницы определяет контекст h1; редактор не должен выбирать заголовок ради размера. Валидация нужна до публикации.","assessment":{"basic":"Задаёт модель блоков.","confident":"Разделяет стиль и семантику. Зафиксировать разрешённые блоки, уровни заголовков, подписи медиа и правила ссылок.","deep":"Шаблон сопоставляет логические уровни редактора контексту страницы, сохраняя вложенность и проверяя итоговый документ."},"followUps":[{"kind":"support","question":"Может ли визуальный размер заголовка определять его уровень?","expected":"Нет; уровень зависит от структуры документа."},{"kind":"transfer","question":"Материал теперь встраивают внутрь страницы с собственным h1. Как сохранить структуру?","expected":"Шаблон сопоставляет логические уровни редактора контексту страницы, сохраняя вложенность и проверяя итоговый документ."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Одну статью CMS показывают в нескольких шаблонах. Спроектируйте правила редакторских блоков и проверку перед публикацией."},
{"id":"html:offline-submit","topic":"html","tab":"senior","ordinal":14,"targetLevel":"senior","angles":[],"kind":"case","title":"Как не потерять ввод при обрыве сети во время отправки?","shortAnswer":"Сохранить форму на странице, показать статус и обеспечить безопасный повтор запроса.","explanation":"HTTP-ошибка и неизвестный результат после разрыва — разные ситуации. Идемпотентный серверный ключ предотвращает дубли, HTML сам этого не гарантирует.","assessment":{"basic":"Сохраняет введённые данные.","confident":"Различает состояния отправки. Сохранить форму на странице, показать статус и обеспечить безопасный повтор запроса.","deep":"Черновик и устойчивый идентификатор операции либо проверка её статуса; повтор согласуется с серверной идемпотентностью."},"followUps":[{"kind":"support","question":"Можно ли считать сетевой таймаут доказательством отсутствия записи?","expected":"Нет; сервер мог завершить операцию без доставленного ответа."},{"kind":"transfer","question":"Пользователь перезагрузил страницу перед повтором. Какие сведения понадобятся?","expected":"Черновик и устойчивый идентификатор операции либо проверка её статуса; повтор согласуется с серверной идемпотентностью."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"После отправки длинной заявки связь оборвалась; неизвестно, сохранил ли её сервер. Спроектируйте восстановление без потери текста и дублей."},
{"id":"html:semantic-migration","topic":"html","tab":"senior","ordinal":15,"targetLevel":"senior","angles":[],"kind":"case","title":"Как заменить div-интерфейс семантическим без регрессий?","shortAnswer":"Инвентаризировать действия, выбрать native элементы и проверить клавиатурные и формовые последствия.","explanation":"Button меняет default type, ссылки — навигацию и контекстное меню. Миграцию проверяют поведением, а не количеством новых тегов.","assessment":{"basic":"Находит интерактивные div.","confident":"Учитывает submit и href. Инвентаризировать действия, выбрать native элементы и проверить клавиатурные и формовые последствия.","deep":"Проверить старую ручную обработку клавиш вместе с нативной активацией; убрать дублирование, сохранив контракт."},"followUps":[{"kind":"support","question":"Что может сделать button внутри формы без явного type?","expected":"Стать кнопкой отправки и изменить поведение формы."},{"kind":"transfer","question":"После миграции действие срабатывает дважды с клавиатуры. Где искать причину?","expected":"Проверить старую ручную обработку клавиш вместе с нативной активацией; убрать дублирование, сохранив контракт."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Спланируйте поэтапную замену кликабельных div ссылками и кнопками в старом приложении. Обоснуйте проверки и порядок выпуска."},
{"id":"html:duplicate-id","topic":"html","tab":"advanced","ordinal":1,"targetLevel":"middle","angles":["engineering","nuance"],"kind":"case","title":"Два поля имеют один id: что сломается?","shortAnswer":"Связи label, фрагменты и DOM-поиск становятся неоднозначными.","explanation":"Уникальность id — контракт документа. Генерировать идентификатор нужно стабильно, особенно между SSR и клиентом.","assessment":{"basic":"Видит нарушение уникальности.","confident":"Находит связи for и href. Связи label, фрагменты и DOM-поиск становятся неоднозначными.","deep":"Все IDREF-связи: for, aria-describedby, aria-labelledby и фрагменты, сохранив согласованность SSR и клиента."},"followUps":[{"kind":"support","question":"Как узнать, с каким контролом реально связана подпись?","expected":"Проверить label.control и сопоставить его с ожидаемым полем."},{"kind":"transfer","question":"После исправления id сломались ссылки на ошибки. Что ещё надо обновить?","expected":"Все IDREF-связи: for, aria-describedby, aria-labelledby и фрагменты, сохранив согласованность SSR и клиента."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Два экземпляра формы имеют одинаковые id; подпись фокусирует чужое поле. Исправьте генерацию идентификаторов при SSR и на клиенте."},
{"id":"html:checkbox-default","topic":"html","tab":"advanced","ordinal":2,"targetLevel":"middle","angles":["nuance"],"kind":"question","title":"Почему checkbox без value отправляет on?","shortAnswer":"on — значение по умолчанию для отмеченного checkbox без value.","explanation":"Неотмеченный checkbox вообще не отправляется. Сервер должен трактовать отсутствие отдельно от строкового значения false.","assessment":{"basic":"Называет on.","confident":"Объясняет отсутствие поля. on — значение по умолчанию для отмеченного checkbox без value.","deep":"Явно согласовать кодирование с сервером, включая порядок и поведение скрытого поля либо клиентского преобразования."},"followUps":[{"kind":"support","question":"Что определяет участие checkbox в отправке?","expected":"Состояние checked, а не смысл строки value."},{"kind":"transfer","question":"Сервер ждёт явный false для снятого флажка. Как исключите неоднозначность нескольких значений?","expected":"Явно согласовать кодирование с сервером, включая порядок и поведение скрытого поля либо клиентского преобразования."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Объясните, почему сервер получает on от выбранного checkbox и ничего от снятого. Предложите однозначный контракт, включая value=\"false\"."},
{"id":"html:button-outside","topic":"html","tab":"advanced","ordinal":3,"targetLevel":"middle","angles":["nuance"],"kind":"question","title":"Как отправить форму кнопкой вне неё?","shortAnswer":"Указать form с id нужной формы и type=\"submit\".","explanation":"Связь не требует DOM-вложенности. Но id должен быть уникальным, а метод отправки влияет на валидацию и submit-событие.","assessment":{"basic":"Знает атрибут form.","confident":"Сохраняет submit-семантику. Указать form с id нужной формы и type=\"submit\".","deep":"Обновлять связь с активной формой, проверять submitter и отсутствие отправки неактивных данных."},"followUps":[{"kind":"support","question":"Как кнопка может сослаться на конкретную форму?","expected":"Атрибутом form с её уникальным id."},{"kind":"transfer","question":"Появились две формы и одна панель. Как проверите переключение?","expected":"Обновлять связь с активной формой, проверять submitter и отсутствие отправки неактивных данных."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"«Сохранить» находится вне формы в закреплённой панели. Сохраните нативную проверку и submit, показав разметку и программный запуск."},
{"id":"html:disabled-fieldset","topic":"html","tab":"advanced","ordinal":4,"targetLevel":"middle","angles":["nuance"],"kind":"question","title":"Все ли потомки disabled fieldset отключены?","shortAnswer":"Обычно да, кроме потомков первого legend этого fieldset.","explanation":"Исключение позволяет оставить управление группой в legend. Нельзя заменить это общим CSS-селектором и считать семантику сохранённой.","assessment":{"basic":"Знает наследование disabled.","confident":"Называет исключение legend. Обычно да, кроме потомков первого legend этого fieldset.","deep":"Нет; исключение относится к первому legend, поэтому новый контрол требует отдельного решения."},"followUps":[{"kind":"support","question":"Какое исключение есть у disabled fieldset?","expected":"Потомки первого legend не отключаются этим fieldset."},{"kind":"transfer","question":"Добавили второй legend с ещё одним контролом. Получит ли он исключение?","expected":"Нет; исключение относится к первому legend, поэтому новый контрол требует отдельного решения."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"В отключённом fieldset внутри первого legend есть флажок включения группы. Предскажите его доступность и данные отправки.","questionCode":"<fieldset disabled>\n  <legend><label><input type=\"checkbox\"> Включить настройки</label></legend>\n  <input name=\"details\" value=\"Текст\">\n</fieldset>","questionCodeLanguage":"html"},
{"id":"html:template-clone","topic":"html","tab":"advanced","ordinal":5,"targetLevel":"middle","angles":["nuance"],"kind":"question","title":"Почему содержимое template не видно и не ищется как обычный потомок?","shortAnswer":"Оно хранится в отдельном DocumentFragment — template.content.","explanation":"При клонировании переносится структура, но обработчики addEventListener не копируются. Нужны повторная привязка или делегирование.","assessment":{"basic":"Обращается к content.","confident":"Клонирует fragment. Оно хранится в отдельном DocumentFragment — template.content.","deep":"Нет; подключить обработчики экземплярам либо использовать делегирование и проверить уникальность id."},"followUps":[{"kind":"support","question":"Где искать содержимое template?","expected":"В template.content, отдельном DocumentFragment."},{"kind":"transfer","question":"Обработчик добавили к исходной кнопке через addEventListener. Скопируется ли он при cloneNode?","expected":"Нет; подключить обработчики экземплярам либо использовать делегирование и проверить уникальность id."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Из template создают карточки, но кнопку не удаётся найти, а обработчик не запускается. Объясните создание рабочего экземпляра."},
{"id":"html:tbody-insert","topic":"html","tab":"advanced","ordinal":6,"targetLevel":"middle","angles":["engineering","nuance"],"kind":"case","title":"Почему querySelector('table > tr') не находит серверные строки?","shortAnswer":"HTML-парсер может вставить tbody, сделав tr его потомком.","explanation":"DOM зависит от алгоритма парсинга, а не только от текстового вложения. Явный tbody устраняет неоднозначность для селекторов и SSR.","assessment":{"basic":"Находит tbody в DOM.","confident":"Исправляет структуру. HTML-парсер может вставить tbody, сделав tr его потомком.","deep":"Нет; DOM-операции и HTML-парсинг различаются, поэтому следует явно создавать ожидаемую структуру."},"followUps":[{"kind":"support","question":"Какого промежуточного элемента может не быть в исходной строке?","expected":"tbody, добавленного HTML-парсером."},{"kind":"transfer","question":"Такие же узлы создали DOM-методами. Обязано ли дерево совпасть?","expected":"Нет; DOM-операции и HTML-парсинг различаются, поэтому следует явно создавать ожидаемую структуру."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Строки таблицы видны, но table > tr не находит их после SSR. Объясните расхождение и устойчивое исправление.","questionCode":"<table id=\"report\">\n  <tr><td>Продажи</td><td>42</td></tr>\n</table>\n<script>\n  console.log(document.querySelector(\"table > tr\"));\n</script>","questionCodeLanguage":"html"},
{"id":"html:aria-disabled","topic":"html","tab":"advanced","ordinal":7,"targetLevel":"middle","angles":["engineering","nuance"],"kind":"case","title":"Можно ли отключить ссылку через aria-disabled?","shortAnswer":"Атрибут сообщает состояние, но сам не отменяет переход и обработчики.","explanation":"Нужно определить доступное поведение либо заменить элемент подходящим. CSS pointer-events не блокирует клавиатурную активацию.","assessment":{"basic":"Не ожидает блокировки от ARIA.","confident":"Учитывает клавиатуру. Атрибут сообщает состояние, но сам не отменяет переход и обработчики.","deep":"Кнопка запускает действие, ссылка ведёт к готовому ресурсу; определить доступные состояния и ожидание."},"followUps":[{"kind":"support","question":"Отменяет ли aria-disabled стандартное действие ссылки?","expected":"Нет; атрибут сообщает состояние."},{"kind":"transfer","question":"Операция стала запускать генерацию отчёта, а затем выдавать ссылку. Как разделите элементы?","expected":"Кнопка запускает действие, ссылка ведёт к готовому ресурсу; определить доступные состояния и ожидание."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Серая ссылка с aria-disabled=\"true\" продолжает скачивать отчёт. Определите необходимый контракт и реализацию для мыши и клавиатуры.","questionCode":"<a href=\"/report.csv\" aria-disabled=\"true\">Скачать отчёт</a>","questionCodeLanguage":"html"},
{"id":"html:accessible-name","topic":"html","tab":"advanced","ordinal":8,"targetLevel":"middle","angles":["engineering","nuance"],"kind":"case","title":"Почему aria-label скрыл видимый текст кнопки от скринридера?","shortAnswer":"aria-label участвует в вычислении имени и может заменить имя из содержимого.","explanation":"Имя должно включать видимую подпись, чтобы работало голосовое управление. Для пояснения используют description, не подмену имени.","assessment":{"basic":"Различает имя и описание.","confident":"Сохраняет видимую подпись. aria-label участвует в вычислении имени и может заменить имя из содержимого.","deep":"Сохранить узнаваемое имя и связать актуальное пояснение описанием; проверить, что смена суммы не скрывает действие."},"followUps":[{"kind":"support","question":"Какое имя получит кнопка в приведённом примере?","expected":"«Подтвердить заказ»: aria-label заменяет имя из видимого содержимого «Оплатить» в этом примере."},{"kind":"transfer","question":"Пояснение «спишется 500 рублей» меняется при выборе тарифа. Как его связать?","expected":"Сохранить узнаваемое имя и связать актуальное пояснение описанием; проверить, что смена суммы не скрывает действие."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Кнопка «Оплатить» объявляется как «Подтвердить заказ» из-за aria-label. Исправьте имя и дополнительное пояснение, сохранив голосовую активацию.","questionCode":"<button aria-label=\"Подтвердить заказ\">Оплатить</button>","questionCodeLanguage":"html"},
{"id":"html:dialog-top-layer","topic":"html","tab":"advanced","ordinal":9,"targetLevel":"middle","angles":["nuance"],"kind":"question","title":"Почему z-index:999999 не перекрывает модальный dialog?","shortAnswer":"showModal помещает dialog в top layer вне обычного порядка наложения.","explanation":"Увеличение z-index соседнего элемента не меняет слой. Popover и полноэкранные элементы тоже взаимодействуют с top layer.","assessment":{"basic":"Называет top layer.","confident":"Не пытается лечить z-index. showModal помещает dialog в top layer вне обычного порядка наложения.","deep":"Предпочесть понятную последовательность действий внутри текущего диалога либо явно управлять вложенной модальностью и фокусом."},"followUps":[{"kind":"support","question":"В каком слое находится модальный dialog?","expected":"В top layer, выше обычных контекстов наложения."},{"kind":"transfer","question":"Уведомление требует действия, блокирующего закрытие окна. Как оцените второй слой?","expected":"Предпочесть понятную последовательность действий внутри текущего диалога либо явно управлять вложенной модальностью и фокусом."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Уведомление с огромным z-index остаётся под showModal-диалогом. Объясните причину и предложите доступное размещение сообщения."},
{"id":"html:shadow-event","topic":"html","tab":"advanced","ordinal":10,"targetLevel":"senior","angles":["nuance"],"kind":"question","title":"Почему event.target меняется при выходе из shadow DOM?","shortAnswer":"Retargeting скрывает внутреннюю структуру компонента.","explanation":"Composed-события могут пересекать границу; composedPath показывает доступный путь. Закрытый shadow root дополнительно скрывает внутренние узлы.","assessment":{"basic":"Знает retargeting.","confident":"Различает bubbles и composed. Retargeting скрывает внутреннюю структуру компонента.","deep":"На доступность внутренних узлов через composedPath; публичные события должны передавать необходимые данные сами."},"followUps":[{"kind":"support","question":"Всегда ли внешний target обязан быть внутренней кнопкой?","expected":"Нет; retargeting может показывать хост."},{"kind":"transfer","question":"Компонент перевели в closed shadow root. На что нельзя опираться интеграции?","expected":"На доступность внутренних узлов через composedPath; публичные события должны передавать необходимые данные сами."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Внешний обработчик компонента видит другой event.target, чем внутренняя кнопка Shadow DOM. Объясните событие и предложите публичный контракт."},
{"id":"html:submitter","topic":"html","tab":"advanced","ordinal":11,"targetLevel":"middle","angles":["engineering","nuance"],"kind":"case","title":"Две submit-кнопки: как определить выбранное действие?","shortAnswer":"Использовать SubmitEvent.submitter и корректные name/value кнопок.","explanation":"Запуск через Enter может выбрать кнопку по правилам формы. requestSubmit(button) сохраняет submitter и нативную проверку.","assessment":{"basic":"Находит submitter.","confident":"Использует name/value. Использовать SubmitEvent.submitter и корректные name/value кнопок.","deep":"Прямой submit обходит обычную проверку и событие submit; для соответствующего пути рассмотреть requestSubmit."},"followUps":[{"kind":"support","question":"Как узнать кнопку, инициировавшую submit?","expected":"Через SubmitEvent.submitter, учитывая возможность отсутствия кнопки."},{"kind":"transfer","question":"Код вызывает form.submit(). Какие этапы обычного пути нужно пересмотреть?","expected":"Прямой submit обходит обычную проверку и событие submit; для соответствующего пути рассмотреть requestSubmit."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Форма имеет «Черновик» и «Опубликовать». Спроектируйте различение действий при клике, Enter и программной отправке с нативной проверкой.","questionCode":"<form id=\"editor\" action=\"/save\" method=\"post\">\n  <input name=\"title\" required>\n  <button type=\"submit\" name=\"action\" value=\"draft\">Сохранить черновик</button>\n  <button type=\"submit\" name=\"action\" value=\"publish\">Опубликовать</button>\n</form>","questionCodeLanguage":"html"},
{"id":"html:image-cors-canvas","topic":"html","tab":"advanced","ordinal":12,"targetLevel":"senior","angles":["engineering","nuance"],"kind":"case","title":"Картинка видна, но чтение canvas запрещено: почему?","shortAnswer":"Рисование cross-origin изображения без CORS может сделать canvas origin-unclean.","explanation":"Отображение ресурса и доступ к его пикселям имеют разные ограничения. Нужны корректный crossorigin до загрузки и разрешающий серверный ответ.","assessment":{"basic":"Различает показ и чтение.","confident":"Знает CORS-условия. Рисование cross-origin изображения без CORS может сделать canvas origin-unclean.","deep":"Настроить режим до начала загрузки, проверить CORS-ответ и перерисовать на чистом canvas подходящим ресурсом."},"followUps":[{"kind":"support","question":"Равнозначны ли разрешение показать изображение и читать его пиксели?","expected":"Нет; canvas может потерять origin-clean после внешнего изображения."},{"kind":"transfer","question":"crossOrigin установили после src. Как построите надёжную проверку?","expected":"Настроить режим до начала загрузки, проверить CORS-ответ и перерисовать на чистом canvas подходящим ресурсом."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Партнёрское изображение отображается и рисуется на canvas, но экспорт завершается ошибкой. Найдите условия отказа и порядок исправления."},
{"id":"html:iframe-sandbox-origin","topic":"html","tab":"advanced","ordinal":13,"targetLevel":"senior","angles":["engineering","nuance"],"kind":"case","title":"Почему allow-scripts вместе с allow-same-origin требует осторожности?","shortAnswer":"Для same-origin содержимого комбинация может позволить снять sandbox через доступ к родителю.","explanation":"Изоляцию оценивают по origin и возможностям, не по наличию атрибута sandbox. Недоверенный контент лучше отдавать с отдельного origin.","assessment":{"basic":"Видит опасную комбинацию.","confident":"Объясняет условие same-origin. Для same-origin содержимого комбинация может позволить снять sandbox через доступ к родителю.","deep":"Проверять origin, источник окна и схему сообщения; отдельный origin не делает любые сообщения доверенными."},"followUps":[{"kind":"support","question":"Какой доступ даёт совпадающий origin при разрешённых скриптах?","expected":"Код может получить доступ к родителю и подорвать sandbox в этом сценарии."},{"kind":"transfer","question":"Виджет перенесли на отдельный origin. Какая проверка остаётся у postMessage?","expected":"Проверять origin, источник окна и схему сообщения; отдельный origin не делает любые сообщения доверенными."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Same-origin iframe имеет allow-scripts и allow-same-origin. Оцените достаточность изоляции непроверенного кода и предложите границу доверия."},
{"id":"html:dom-clobbering","topic":"html","tab":"advanced","ordinal":14,"targetLevel":"senior","angles":["engineering","nuance"],"kind":"case","title":"Как именованные элементы могут повлиять на старый глобальный код?","shortAnswer":"Некоторые name/id доступны через именованный доступ к Window или формам и могут затенять ожидаемые значения.","explanation":"Нельзя считать window.config доверенной переменной только по имени. Использовать модульную область и проверять типы значений.","assessment":{"basic":"Распознаёт named access.","confident":"Избегает неявных глобальных. Некоторые name/id доступны через именованный доступ к Window или формам и могут затенять ожидаемые значения.","deep":"Нет; именованный доступ остаётся риском, нужны ограничения разметки и явные ссылки на данные без доверия к глобальным именам."},"followUps":[{"kind":"support","question":"Что может затенить form.submit?","expected":"Контрол с соответствующим name или id может затенять свойство формы."},{"kind":"transfer","question":"Разрешили произвольные id, но удалили script. Достаточно ли этого?","expected":"Нет; именованный доступ остаётся риском, нужны ограничения разметки и явные ссылки на данные без доверия к глобальным именам."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"После вставки пользовательской разметки window.config и form.submit перестали обозначать ожидаемые значения. Объясните воспроизведение и защиту.","questionCode":"<form id=\"settings\">\n  <input name=\"submit\" value=\"save\">\n</form>\n<script>\n  const form = document.getElementById(\"settings\");\n  form.submit();\n</script>","questionCodeLanguage":"html"},
{"id":"html:html-parser-context","topic":"html","tab":"advanced","ordinal":15,"targetLevel":"senior","angles":["nuance"],"kind":"question","title":"Почему один HTML-фрагмент даёт разные деревья в div и table?","shortAnswer":"Алгоритм фрагментного парсинга зависит от контекстного элемента.","explanation":"Табличные режимы вставки и foster parenting могут переместить узлы. Универсальная конкатенация строк без контекста ненадёжна.","assessment":{"basic":"Учитывает контекст парсинга.","confident":"Объясняет табличные исправления. Алгоритм фрагментного парсинга зависит от контекстного элемента.","deep":"Безопасность и структуру в конечном контексте; промежуточная обработка не заменяет проверку реальной вставки."},"followUps":[{"kind":"support","question":"Что кроме строки является входом фрагментного парсинга?","expected":"Контекстный элемент, например div или table."},{"kind":"transfer","question":"Санитаризацию выполнили в div, а результат вставили в таблицу. Что проверите?","expected":"Безопасность и структуру в конечном контексте; промежуточная обработка не заменяет проверку реальной вставки."}],"context":"HTML Living Standard; современный браузер. Доступность проверяется также в целевых браузере и скринридере.","references":["https://html.spec.whatwg.org/multipage/"],"verifiedAt":"2026-11-13","question":"Одинаковая строка даёт разные DOM-деревья при вставке в div и table. Предложите воспроизведение и устойчивый способ вставки недоверенного содержимого."}
);
